            ->orderBy('nome')
            ->get(),
    ]);
}

// Route: GET /{{ajaxUrl:api/registros}}
public function index(Request $request)
{
    $columns = ['id', 'nome', 'email'];
    $query   = Modelo::query();

    if ($search = $request->input('search.value')) {
        $query->where(fn($q) =>
            $q->where('nome', 'like', '%' . $search . '%')
              ->orWhere('email', 'like', '%' . $search . '%'));
    }

    $total = $query->count();
    $col   = $columns[$request->input('order.0.column', 0)] ?? 'id';
    $dir   = $request->input('order.0.dir', 'asc') === 'desc' ? 'desc' : 'asc';

    $data = $query->orderBy($col, $dir)
        ->skip((int) $request->input('start', 0))
        ->take((int) $request->input('length', 10))
        ->get();

    return response()->json([
        'draw'            => (int) $request->input('draw'),
        'recordsTotal'    => $total,
        'recordsFiltered' => $total,
        'data'            => $data,
    ]);
}

// Marque "Dados vem em HTML": o backend devolve 2 campos fixos:
// html_option (dropdown) e html_selected (item selecionado/chip).
// Busca usa campos planos (searchField = "text,cpf"), NUNCA o HTML.
// Aviso: o HTML e renderizado sem escapar — escape dados de usuario no servidor.
public function index()
{
    return response()->json(
        Cliente::query()->limit(50)->get()->map(fn ($c) => [
            '{{valueField:id}}'   => $c->id,
            '{{labelField:text}}' => $c->nome,   // texto/busca + fallback
            'cpf'           => $c->cpf,          // opcional, para busca
            'html_option'   => view('partials.cliente_option', ['c' => $c])->render(),
            'html_selected' => '<strong>'.e($c->nome).'</strong>',
        ])
    );
}

