            ->orderBy('{{labelField:text}}')
            ->get()
    );
}

// Route: GET /{{ajaxUrl:api/itens}}?{{searchParam:q}}=termo
public function index(Request $request)
{
    $query = Item::select('{{valueField:id}}', '{{labelField:text}}');

    if ($request->filled('{{searchParam:q}}')) {
        $query->where('{{labelField:text}}', 'like',
            '%' . $request->input('{{searchParam:q}}') . '%');
    }

    return response()->json($query->limit({{maxOptions:50}})->get());
}

