// Route: POST /{{action:#}}
public function store(Request $request)
{
    $request->validate([
        '{{name:file}}' => 'required|file|max:10240',
    ]);

    $path = $request->file('{{name:file}}')
        ->store('uploads', 'public');

    return response()->json(['path' => $path], 201);
}

// O campo hidden name='{{inputName:barcode}}' e enviado com o codigo lido.
// Route: POST /processar
public function processar(Request $request)
{
    $codigo = $request->input('{{inputName:barcode}}');

    $produto = Produto::where('codigo_barras', $codigo)->firstOrFail();

    return response()->json(['produto' => $produto]);
}

