// Route: GET /{{dataUrl:api/gantt}}
// JSON: { resources: [{id,label,group?}], tasks: [{id,resourceId,start,end,label,color?,url?,status?}] }
public function index()
{
    return response()->json([
        'resources' => Recurso::all()->map(fn($r) => [
            'id' => $r->id, 'label' => $r->nome, 'group' => $r->grupo,
        ]),
        'tasks' => Reserva::all()->map(fn($t) => [
            'id' => $t->id, 'resourceId' => $t->recurso_id,
            'start' => $t->inicio->toIso8601String(),
            'end'   => $t->fim->toIso8601String(),
            'label' => $t->titulo, 'color' => $t->cor ?? 'blue',
            'url' => route('reservas.show', $t->id), 'status' => $t->status,
        ]),
    ]);
}
